body.script:
  /* Supabase configuration */
const SUPA_URL='https://kgttekpnmkjgkzauekso.supabase.co',SUPA_KEY='sb_publishable_4aOkK0OlfbjiO_F38YD_8g_yPL4BXR4'; // clé publique : sans risque dans un site web
const sb=supabase.createClient(SUPA_URL,SUPA_KEY);

// Modules disponibles pour le centre connecté 
let FG_MODULES = []; let FG_SELECTED_MODULES = []; let FG_MODULE_DOMAINS = []; 

async function fgLoadModuleCatalogue() { 
  const container = document.getElementById("fgModuleBadges");
  const note = document.getElementById("fgModuleSelectedNote");
   if (!CURRENT_CENTRE_ID) { note.textContent = "Aucun centre sélectionné."; return; }
// Charger les modules associés au centre 

const { data: associations, error: errorAssociations }= await sb .from("centre_matieres") 
.select("matiere_id") .eq("centre_id", CURRENT_CENTRE_ID);
 if (errorAssociations) 
 { console.error("Erreur de chargement :", errorAssociations);
  note.textContent = "Impossible de charger les modules.";
   return; }
 const ids = (associations || []).map(item => item.matiere_id); 
 if (ids.length === 0) { 
  FG_MODULES = []; fgRenderModuleBadges();
   note.textContent = "Aucun module dans le catalogue de ce centre.";
    return;
   } 
   // Charger les informations des modules 

   const { data: modules, error: errorModules } = await sb .from("matieres") 
   .select("id, nom, domaine_id")
    .in("id", ids) .order("nom");
   if (errorModules) 
   { console.error("Erreur de chargement des modules :", errorModules);
    note.textContent = "Impossible de charger les noms des modules."; 
    return; }

  FG_MODULES = modules || []; fgRenderModuleBadges(); }

/** Charger les domaines disponibles **/ 

async function fgLoadModuleDomains() { 
  const select = document.getElementById("fgNewModuleDomain");
  const { data, error } = await sb 
  .from("domaines") 
  .select("id, nom, couleur") 
  .order("nom");

  if (error) { 
    console.error("Erreur de chargement des domaines :", error);
   document.getElementById("fgNewModuleNote")
   .textContent = "Impossible de charger les domaines.";
    return false; 
  } 

  FG_MODULE_DOMAINS = data || [];
   select.innerHTML = 'Choisir un domaine';
    FG_MODULE_DOMAINS.forEach(domaine => {
       const option = document.createElement("option")
       ; option.value = domaine.id; option.textContent = domaine.nom;
        select.appendChild(option); 
      });
       return true;
  }


 function fgRenderModuleBadges() {
     const container = document.getElementById("fgModuleBadges");
     const search = document.getElementById("fgModuleSearch");
     const note = document.getElementById("fgModuleSelectedNote");
      if (!container || !search || !note) return;
       const query = search.value.trim().toLowerCase();
       const filtered = FG_MODULES.filter(module => module.nom.toLowerCase().includes(query) );
      container.innerHTML = ""; 

    if (filtered.length === 0) { 
      container.textContent = "Aucun module trouvé."; } 
      filtered.forEach(module => { const button = document.createElement("button"); button.type = "button";
      button.textContent = (FG_SELECTED_MODULES.includes(module.id) ? "✓ " : "+ ") + module.nom;
      button.style.cssText = ` padding: 8px 12px; border-radius: 20px; border: 1px solid #cbd5e1; cursor: pointer; background: ${ FG_SELECTED_MODULES.includes(module.id) ? "#dbeafe" : "#ffffff" }; color: #1e293b; `;
      button.addEventListener("click", () => { 
        if (FG_SELECTED_MODULES.includes(module.id)) { 
          FG_SELECTED_MODULES = FG_SELECTED_MODULES.filter( id => id !== module.id );
         } else {
           FG_SELECTED_MODULES.push(module.id);
           } 
        fgRenderModuleBadges(); 
      });
       container.appendChild(button);
      });

      note.textContent = FG_SELECTED_MODULES.length + " module(s) sélectionné(s)."; } // Rechercher un module document .getElementById("fgModuleSearch") .addEventListener("input", fgRenderModuleBadges);


/** Afficher les modules sélectionnés dans le formulaire  **/

function fgRenderSelectedModuleBadges() {
    const container = $('fgSelectedModuleBadges');
    const note = $('fgModuleSelectedNote'); 
    if (!container || !note) return; 
    container.innerHTML = ''; 
    const selectedModules = FG_MODULES.filter(module => FG_SELECTED_MODULES.includes(Number(module.id)) );
    selectedModules.forEach(module => { const badge = document.createElement('span'); 
    badge.textContent = module.nom; 
    badge.style.cssText = ` display:inline-block; padding:5px 10px; border-radius:15px; background:#dbeafe; color:#1d4ed8; font-size:13px; `; 
    container.appendChild(badge); }); 
    note.textContent = selectedModules.length ? selectedModules.length + ' module(s) sélectionné(s).' : 'Aucun module sélectionné.';
   }



    /** Afficher ou masquer le formulaire de nouveau module **/

document .getElementById("fgShowNewModule") .addEventListener("click", () => {
   const box = document.getElementById("fgNewModuleBox"); 
   const isHidden = box.style.display === "none";
    box.style.display = isHidden ? "grid" : "none";

  if (isHidden) { document.getElementById("fgNewModuleName").focus(); 

  } });



  /** Créer un module et l'associer au centre connecté **/ 

  document .getElementById("fgCreateModule") 
  .addEventListener("click", async () => {
     const nameInput = document.getElementById("fgNewModuleName");
      const domainInput = document.getElementById("fgNewModuleDomain");
       const note = document.getElementById("fgNewModuleNote");
        const createButton = document.getElementById("fgCreateModule");
         const nom = nameInput.value.trim();
          const domaineId = Number(domainInput.value);
       if (!me || me.role !== "Admin") {
         note.textContent = "Action réservée à un administrateur.";
          return; 
        } 
      if (!CURRENT_CENTRE_ID) {
         note.textContent = "Centre introuvable."; return; 
        }
       if (!nom || !domaineId) {
         note.textContent = "Saisis le nom et choisis un domaine.";
          return; 
        } 
      const domaine = FG_MODULE_DOMAINS.find( d => Number(d.id) === domaineId ); 
      if (!domaine) {
         note.textContent = "Domaine invalide."; return; 
        }
      const dejaPresent = FG_MODULES.some( m => m.nom.trim().toLowerCase() === nom.toLowerCase() );
       if (dejaPresent) { note.textContent = "Ce module existe déjà dans le catalogue."; 
       return;
       } 

       createButton.disabled = true; note.textContent = "Création en cours..."; 
       try { 

        /** Créer la matière **/
         const codeBase = nom .normalize("NFD")
          .replace(/[\u0300-\u036f]/g, "") 
          .toLowerCase() .replace(/[^a-z0-9]+/g, "-") 
          .replace(/^-|-$/g, ""); const code = (codeBase || "module") + "-" + Math
          .random().toString(36)
          .slice(2, 8); 

          const { data: matiere, error: matiereError } = await sb 
          .from("matieres")
          .insert({
            nom: nom,
            code: code,
            domaine_id: domaineId,
            icone: "book"
          }) 
          .select("id, nom, domaine_id, icone")
          .single();

        if (matiereError) throw matiereError;

           /** Associer le module au centre **/

           const { error: associationError } = await sb 
           .from("centre_matieres")
           .insert({ centre_id: CURRENT_CENTRE_ID, matiere_id: matiere.id });

           if (associationError) { 
            console.error( "Le module a été créé, mais son association a échoué :", associationError );
            note.textContent = "Module créé, mais association au centre impossible : " + associationError.message;
             return; }
              /** Ajouter le module au catalogue affiché **/
            FG_MODULES.push(matiere); 
            FG_MODULES.sort((a, b) => a.nom.localeCompare(b.nom));

            /** Le sélectionner automatiquement **/

            if (!FG_SELECTED_MODULES.includes(Number(matiere.id))) {
               FG_SELECTED_MODULES.push(Number(matiere.id)); } 

               fgRenderModuleBadges(); 
               nameInput.value = ""; 
               domainInput.value = "";
                note.textContent = "Module créé et sélectionné avec succès."; 
              } catch (error) { 
                console.error("Erreur de création du module :", error);
                 note.textContent = "Erreur : " + (error.message || "création impossible."); 
                } finally {
                   createButton.disabled = false; } });

/** Charger les modules déjà associés à une formation**/
 async function fgLoadFormationModules(formationId) {
   const { data, error } = await sb 
   .from("formation_matieres") 
   .select("matiere_id") 
   .eq("formation_id", formationId);

   if (error) { 
    console.error( "Erreur de chargement des modules de la formation :", error );
    document.getElementById("fgFormationNote").textContent = "Impossible de charger les modules associés.";
     return false; }
   FG_SELECTED_MODULES = (data || []).map( item => Number(item.matiere_id) );
  fgRenderModuleBadges(); return true;
 }

 /** Enregistrer les modules sélectionnés pour une formation **/
async function fgSaveFormationModules(formationId) {
   const { data: existing, error: readError } = await sb 
   .from("formation_matieres") 
   .select("matiere_id") 
   .eq("formation_id", formationId); 

   if (readError) {
     console.error("Erreur de lecture des associations :", readError);
      return readError; }

   const existingIds = (existing || []).map( item => Number(item.matiere_id) );
   const selectedIds = [...new Set( FG_SELECTED_MODULES.map(Number) )];
   const toAdd = selectedIds.filter( id => !existingIds.includes(id) );
   const toRemove = existingIds.filter( id => !selectedIds.includes(id) );
    if (toAdd.length > 0) {
       const { error } = await sb 
       .from("formation_matieres") 
       .insert(toAdd.map(matiereId => ({ formation_id: formationId, matiere_id: matiereId }))); 
         if (error) { console.error("Erreur d'ajout des modules :", error);
          return error; 
        } } 
            if (toRemove.length > 0) {
               const { error } = await sb
                .from("formation_matieres") 
                .delete() 
                .eq("formation_id", formationId) 
                .in("matiere_id", toRemove);
                   if (error) {
                     console.error("Erreur de suppression des modules :", error);
                      return error; 
                    } } return null; 
                  }

  /*** Afficher les modules sous forme de badge ***/ 


