const T=[];
const DAYS=['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'],ROOMS=[],RI={},H0=8,HR=56;
let C=[];
let nid=100,me=null;

let CURRENT_CENTRE_ID=null;
let CURRENT_CENTRE_NAME='';
let SUPER_CENTRES=[];




let CENTRE_DROITS={};

/*
 * Les droits du centre ne sont plus lus directement depuis `centres.droits`.
 * On passe par mc_droit(), fonction SECURITY DEFINER déjà présente en base,
 * afin que le RLS sur `centres` ne puisse pas faire échouer silencieusement
 * le contrôle des fonctionnalités.
 */

async function loadCentreDroits(){

  CENTRE_DROITS={};

  if(!me || me.sup)
    return;

  const keys=[
    'etudiants',
    'formateurs',
    'cours',
    'planning',
    'salles',
    'presences',
    'certificats',
    'supports',
    'documents',
    'statistiques',
    'rapports',
    'import_excel',
    'export_excel'
  ];

  const results=await Promise.all(
    keys.map(async key=>{
      const r=await sb.rpc('mc_droit',{p_droit:key});
      return [key, !r.error && r.data===true];
    })
  );

  results.forEach(([key,ok])=>{
    CENTRE_DROITS[key]=ok;
  });
}

/* ---------- Vérification d'un droit du centre ---------- */

function droitActif(key){

  if(me && me.sup)
    return true;

  /* Fail-closed : un droit non confirmé reste désactivé. */
  return CENTRE_DROITS[key]===true;
}


/* ---------- Application des droits du centre ---------- */
function appliquerDroitsCentre(){

  if(me && me.sup) return;

  const exigencesOnglets={
    vcal:['planning'],
    vl:['cours'],
    vr:['salles'],
    /* Le module Supports/Documents est un seul onglet dans l'UI actuelle.
       Il n'apparaît que si les deux droits associés sont actifs. */
    vk:['supports','documents'],
    vf:['formateurs'],
    vp:['presences'],
    vs:['etudiants'],
    vc:['certificats'],
    vd:['statistiques']
  };

  Object.entries(exigencesOnglets).forEach(
    ([tabId,required])=>{

      const btn=document.querySelector(
        `.tabs button[data-v="${tabId}"]`
      );

      if(!btn)return;

      /* Supports reste toujours accessible aux formateurs. */
if(me && me.role==='Formateur' && (tabId==='vk' || tabId==='vp')) return;
      const droitOk=required.every(droitActif);

      /* Les droits du centre ne doivent jamais pouvoir
         ré-ouvrir une rubrique interdite par le rôle.
         Le menu par rôle décide de la visibilité de départ ;
         ici on ne fait que retirer la rubrique si le droit est désactivé. */
      if(!droitOk){
        btn.classList.add('hidden');
        btn.style.setProperty('display','none','important');
      }
    }
  );
}



const ctr=()=>me&&me.sup&&CURRENT_CENTRE_ID
  ?{centre_id:CURRENT_CENTRE_ID}
  :{};
/* ---------- Fonctions utilitaires ---------- */
const $=id=>document.getElementById(id);
const fmt=h=>Math.floor(h)+'h'+(h%1?'30':'');
const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const clash=(c,ex)=>C.find(o=>o.d===c.d&&o.s<c.e&&c.s!C.some(o=>o.id!==c.id&&o.d===c.d&&o.s<c.e&&c.s<o.e&&o[key]===val);


/* ---------- Initialisation de l'interface ---------- */
$('poles').innerHTML=Object.values(POLE).map(p=>`${p[0]}`).join('');
const show=id=>{['landing','login','app','pend'].forEach(x=>$(x).classList.toggle('hidden',x!==id));if(id==='landing'){document.querySelectorAll('.lpn [data-go]').forEach(b=>b.textContent=me?'Retour à mon espace':'Se connecter');scrollTo(0,0)}};
document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{if(me)show('app');else{show('login');$('u').focus()}});
document.querySelector('[data-back]').onclick=()=>show('landing');
$('lo').onclick=async()=>{await sb.auth.signOut();me=null;show('landing');$('p').value=''};
$('th').onclick=()=>{const r=document.documentElement,d=r.dataset.theme==='dark'||(!r.dataset.theme&&matchMedia('(prefers-color-scheme:dark)').matches);r.dataset.theme=d?'light':'dark'};

/* ---------- Fonctions utilitaires ---------- */
function opts(el,arr){el.innerHTML=arr.map(([v,l])=>`${l}`).join('')}

/* ---------- Initialisation de l'interface ---------- */
function start(){

  $('wn').textContent=me.name;
  $('wr').textContent=me.role;


  opts($('ft'),[['','Tous les formateurs'],...T.map((t,i)=>[i,t.n])]);
  // opts($('fr'),[['','Toutes les salles'],...ROOMS.map(r=>[r,sn(r)+' · '+RI[r][0]])]);
  if(me.tid!==undefined){$('ft').value=me.tid;$('ft').disabled=true}else $('ft').disabled=false;
  $('lg').innerHTML=Object.values(POLE).map(p=>`${p[0]}`).join('');
  document.body.classList.toggle('isadm',me.role==='Admin'||me.role==='Formateur');

  const salleTools=$('salletools');
  if(salleTools){
    const canEditRooms=!!me && me.role==='Admin' && !me.sup;
    salleTools.classList.toggle('hidden',!canEditRooms);
  }

  /* ---------- Menu par rôle ---------- */
  function appliquerMenuRole(){
    const tous=[...document.querySelectorAll('.tabs button')];

    tous.forEach(btn=>{
      btn.classList.add('hidden');
      btn.style.setProperty('display','none','important');
    });

    const common=['vcal','vr','vk'];
    let visibles=[...common];

    if(me && (
  me.role === 'Admin' ||
  me.role === 'Directeur' ||
  me.sup
)){
  visibles.push(
    'vd','vl','vf','vp','vi','vs',
    'vfg','vc','vh','vpcentre'
  );

  if(me.sup) visibles.push('vz');

}else if(me && me.role === 'Formateur'){

  /* Formateur : pas de Tableau de bord / Rapports. */
  visibles.push('vl','vn','vp');

}else if(me && me.role === 'Étudiant'){

  visibles.push('vm','vq');

}

    visibles.forEach(v=>{
      const btn=document.querySelector(`.tabs button[data-v=\"${v}\"]`);
      if(btn){
        btn.classList.remove('hidden');
        btn.style.setProperty('display','inline-flex','important');
      }
    });
  }

  /* ---------- Menu principal par rôle ---------- */

  document.querySelectorAll('.adm').forEach(e=>e.classList.toggle('hidden',me.role!=='Admin'));
  document.querySelectorAll('.fm').forEach(e=>e.classList.toggle('hidden',me.role!=='Admin'&&me.role!=='Formateur'));
  document.querySelectorAll('.stu').forEach(e=>e.classList.toggle('hidden',me.role!=='Étudiant'));
  document.querySelectorAll('.fo').forEach(e=>e.classList.toggle('hidden',me.role!=='Formateur'));
  document.querySelectorAll('.sup').forEach(e=>e.classList.toggle('hidden',!me.sup));

  appliquerMenuRole();

  if(!$('tabs').querySelector('svg')){$('tabs').querySelectorAll('button').forEach(b=>b.insertAdjacentHTML('afterbegin',ic(b.dataset.i)));$('bc').insertAdjacentHTML('afterbegin',ic('plus'));$('bm').insertAdjacentHTML('afterbegin',ic('cube'));$('bf').insertAdjacentHTML('afterbegin',ic('users'));$('bx').insertAdjacentHTML('afterbegin',ic('cal'))}

  appliquerDroitsCentre();

  // Règle stricte : « Mes étudiants » est réservé au FORMATEUR.
  // Cette règle est appliquée en dernier pour éviter qu'une autre logique
  // de visibilité du menu puisse le rendre visible aux autres rôles.
  const mesEtudiantsBtn = document.querySelector('.tabs button[data-v="vn"]');
  if(mesEtudiantsBtn){
    const visible = !!me && me.role === 'Formateur';
    mesEtudiantsBtn.classList.toggle('hidden', !visible);
    mesEtudiantsBtn.style.setProperty('display', visible ? 'inline-flex' : 'none', 'important');
  }

  // Règle : « Présences » est accessible à l'ADMIN et au FORMATEUR.
const presencesBtn = document.querySelector('.tabs button[data-v="vp"]');


document.querySelector('.tabs button:not(.hidden)')?.click();

chargerFiltresPlanning().catch(err => {
  console.error('Erreur des filtres du planning :', err);
});

  render();
}

['fp','ft'].forEach(i => {
  const el = $(i);
  if (el) el.onchange = render;
});




/* Rend le planning dans le tableau. */
function render(){wkLabel();



  const fp = $('fp').value;
  const fg = $('fgPlanning').value;
  const fm = $('fmPlanning').value;
  const ft = $('ft').value;


const groupeSelectionne = PL_GROUPES.find(
  g => String(g.id) === String(fg)
);

const correspond = c => {
  const cours = RAW.find(
    r => String(r.id) === String(c.id)
  );

  if (!cours) return false;

  // Filtre par formateur
  if (ft !== '' && String(c.t) !== String(ft)) {
    return false;
  }

  // Filtre par module
  if (fm && String(cours.matiere_id) !== String(MID[fm])) {
    return false;
  }

  // Retrouver le groupe associé à la séance
  const groupeCours = PL_GROUPES.find(
    g => String(g.id) === String(cours.groupe_id)
  );

  // Filtre par groupe
  if (fg && String(cours.groupe_id) !== String(fg)) {
    return false;
  }

  // Filtre par formation
  if (fp) {
    if (!groupeCours ||
        String(groupeCours.formation_id) !== String(fp)) {
      return false;
    }
  }

  // Respecter les dates réelles du groupe
  const groupe = groupeSelectionne || groupeCours;
  const date = c.date;

  if (groupe && date) {
    if (groupe.date_debut && date < groupe.date_debut) {
      return false;
    }

    if (groupe.date_fin && date > groupe.date_fin) {
      return false;
    }
  }

  return mine(c);
};

const L = C.filter(c => correspond(c));

const LG = L.concat(
  XC.filter(c => correspond(c))
);

const compteurFormation = document.getElementById('formationProgress');

if (compteurFormation) {
  compteurFormation.hidden = !fp;

  if (fp) {
    document.getElementById('fpPlanned').textContent = '0h';
    document.getElementById('fpDone').textContent = '0h';
    document.getElementById('fpRemaining').textContent = '0h';
    document.getElementById('fpPercent').textContent = '—';
  }
}


  let h='
'+DAYS.map((d,i)=>`
${d}${wdate(i).slice(8)}/${wdate(i).slice(5,7)}`).join('');
  h+='
'+Array.from({length:11},(_,i)=>`
${H0+i}h`).join('')+'';
  DAYS.forEach((_,d)=>{
    h+=`
`+LG.filter(c=>c.d===d).map(c=>{const s=S[c.k];
      return `

      ${me.role==='Admin'?`×`:''}

${ic(s[2])}${s[0]}${fmt(c.s)} – ${fmt(c.e)}${T[c.t].n} · ${sn(c.r)}`}).join('')+'';
  });
  $('grid').innerHTML=h;

  const compteur = document.getElementById('formationProgress');
const filtreFormation = document.getElementById('fp');

if (compteur && filtreFormation) {
  compteur.hidden = !filtreFormation.value;
}

  renderRooms();renderList(L);renderTrainers();renderAgenda(L);
}

/* Rend la liste des formateurs dans le tableau. */
$('grid').onclick=e=>{if(!me||(me.role!=='Admin'&&me.role!=='Formateur'))return;
  const del=e.target.closest('[data-del]');if(del){if(confirm('Supprimer ce cours ?'))sb.from('cours').delete().eq('id',del.dataset.del).then(async()=>{await load();render()});return}
  const card=e.target.closest('.card');if(card){
    if(card.classList.contains('xc')){if(confirm('Rétablir cette séance ?'))sb.from('annulations').delete().eq('cours_id',card.dataset.id).eq('date',card.dataset.date).then(async()=>{await load();render()});return}
    const oc=C.find(c=>c.id==card.dataset.id&&c.date===card.dataset.date);if(oc)openCours(oc);return}
  const col=e.target.closest('.col');
  if(col&&!col.classList.contains('clo')){
    const y=e.clientY-col.getBoundingClientRect().top,h=Math.min(H0+Math.floor(y/HR*2)/2,18.5);
    openCours({d:+col.dataset.d,date:wdate(+col.dataset.d),s:h,e:Math.min(h+2,19),
      r:(+$('fr')?.value)||undefined})}};

/* Rend la liste des créneaux libres pour une salle et un jour donnés. */
function slots(r,d){
  const o=C.filter(c=>c.r===r&&c.d===d).sort((a,b)=>a.s-b.s),f=[];let t=H0;
  o.forEach(c=>{if(c.s>t)f.push(fmt(t)+'–'+fmt(c.s));t=Math.max(t,c.e)});
  if(t<19)f.push(fmt(t)+'–19h');return f}


/* Rend la liste des cours filtrés dans le tableau. */
function renderList(L){
  const R=[...L].sort((a,b)=>a.d-b.d||a.s-b.s);
  $('tb').innerHTML='
CoursHoraireFormateurDomaineSalleDisponibilité de la salle'+
  (R.length?R.map(c=>{const s=S[c.k],v=`var(${POLE[s[1]][1]})`,f=slots(c.r,c.d);
    return `

${ic(s[2])}${s[0]}${DAYS[c.d]}
${fmt(c.s)} – ${fmt(c.e)}${T[c.t].n}${POLE[s[1]][0]}${sn(c.r)}
${RI[c.r][0]}${f.length?'Libre '+DAYS[c.d].toLowerCase()+' : '+f.join(' · '):'Complète ce jour-là'}`}).join(''):'
Aucun cours ne correspond à ces filtres.')+'';
}


/* Rend la liste des salles avec leur état actuel et les créneaux de la semaine. */
function renderRooms(){
  const n=new Date(),cw=iso(monday(n))===iso(WK),dn=cw?(n.getDay()+6)%7:-1,hn=n.getHours()+n.getMinutes()/60;
  $('rooms').innerHTML=ROOMS.map(r=>{
    const L=C.filter(c=>c.r===r),cur=L.find(c=>c.d===dn&&c.s<=hn&&hnc.d===dn&&c.s>hn).sort((a,b)=>a.s-b.s)[0];
    const busy=L.reduce((a,c)=>a+c.e-c.s,0),tot=66;
    const st=dn<0?['c','Autre semaine']:cur?['b',`Occupée jusqu'à ${fmt(cur.e)}`]:(dn>5||hn<8||hn>=19)?['c','Fermée actuellement']:nx?['f',`Libre jusqu'à ${fmt(nx.s)}`]:['f','Libre jusqu\'à la fermeture'];
    const strip=DAYS.map((d,di)=>`
${d.slice(0,3)}`+Array.from({length:11},(_,i)=>{const c=L.find(c=>c.d===di&&c.sH0+i);return ``}).join('')+'').join('');
    const adminActions=canManageRooms()?`
ModifierSupprimer`:'';
    return `

${sn(r)}${st[1]}
${RI[r][0]} · ${RI[r][1]} places${strip}
Occupée ${busy} h / ${tot} hLibre ${tot-busy} hVoir dans le planning${adminActions}`}).join('');
}

/* Rend la liste des formateurs dans le filtre et sélectionne celui de l'utilisateur si applicable. */
function refreshT(){opts($('ft'),[['','Tous les formateurs'],...T.map((t,i)=>[i,t.n])]);$('ft').value=me.tid!==undefined?me.tid:''}

