${ini}${t.n}
${L.length} cours · ${h} h / semaine
${t.s.map(k=>`${S[k][0]}`).join('')}
${t.pid?'Accès actif':'Pas d\'accès'}${t.mail?' · '+esc(t.mail):''}${t.pid?'Réinitialiser le mot de passe':'Créer l\'accès'}Supprimer`}).join('');
}
