$('tf').onsubmit=async e=>{e.preventDefault();const m=$('tm'),ko=t=>{m.className='msg ko';m.textContent=t},n=$('tn').value.trim(),ks=[...document.querySelectorAll('#tfs input:checked')].map(x=>x.value);
