  $('tn').value='';document.querySelectorAll('#tfs input').forEach(x=>x.checked=false);refreshT();trOpts();render()};
const sn=r=>RNM[r]||('Salle '+r);
let EDIT_ROOM_ID=null;

/* Vérifie si l'utilisateur a le droit de gérer les salles.
 * Retourne true si l'utilisateur est un administrateur et n'est pas un super-administrateur.
 * Sinon, retourne false.
 */
function canManageRooms(){
  return !!me && me.role==='Admin' && !me.sup;
}

/* Réinitialise le formulaire de création/modification de salle.
 * Vide les champs et remet le formulaire à l'état initial.
 */
function resetSalleForm(){
  EDIT_ROOM_ID=null;
  $('sltitle').textContent='Ajouter une salle';
  $('slsubmit').textContent='Enregistrer la salle';
  $('slm').textContent='';
  $('slm').className='msg';
  $('sln').value='';
  $('slt').value='';
  $('slc').value='';
  $('slt-l').innerHTML=[...new Set(ROOMS.map(r=>RI[r][0]).filter(Boolean))].map(x=>``).join('');
}
/* Ajouter une salle.
 * Vérifie d'abord si l'utilisateur a le droit de gérer les salles.
 * Si oui, ouvre le formulaire de création de salle.
 */
function openSalleCreate(){
  if(!canManageRooms())return;
  resetSalleForm();
  $('dsl').showModal();
}

/* Modifier une salle.
 * Remplit le formulaire avec les informations de la salle sélectionnée.
 * Vérifie d'abord si l'utilisateur a le droit de gérer les salles.
 * Si oui, ouvre le formulaire de modification avec les données de la salle.
 */

function openSalleEdit(r){
  if(!canManageRooms())return;
  const rid=SID[r];
  if(!rid)return;
  EDIT_ROOM_ID=r;
  $('sltitle').textContent='Modifier la salle';
  $('slsubmit').textContent='Enregistrer les modifications';
  $('slm').textContent='';
  $('slm').className='msg';
  $('sln').value=sn(r);
  $('slt').value=(RI[r]&&RI[r][0])||'';
  $('slc').value=(RI[r]&&RI[r][1])||'';
  $('slt-l').innerHTML=[...new Set(ROOMS.map(x=>RI[x][0]).filter(Boolean))].map(x=>``).join('');
  $('dsl').showModal();
}

/* Supprimer une salle.
 * Vérifie d'abord si la salle est utilisée par un ou plusieurs cours.
 * Si oui, affiche un message d'erreur et n'effectue pas la suppression.
 * Sinon, demande confirmation avant de supprimer la salle de la base de données.
 */
async function deleteSalle(r){
  if(!canManageRooms())return;
  const rid=SID[r];
  if(!rid)return;
  const used=RAW.some(c=>RN[c.salle_id]===r);
  if(used){
    alert('Impossible de supprimer cette salle : elle est encore utilisée par un ou plusieurs cours. Réaffectez d’abord ces cours.');
    return;
  }
  if(!confirm(`Supprimer ${sn(r)} ? Cette action est définitive.`))return;
  let q=sb.from('salles').delete().eq('id',rid);
  if(me.centreId)q=q.eq('centre_id',me.centreId);
  const res=await q;
  if(res.error){alert('Suppression impossible : '+res.error.message);return}
  await load();
  initForm();
  render();
}

$('sla').onclick=openSalleCreate;

$('slf').onsubmit=async e=>{e.preventDefault();
  const m=$('slm'),b=e.submitter,ko=x=>{m.className='msg ko';m.textContent=x};
  const n=$('sln').value.trim().replace(/\s+/g,' '),
    ty=$('slt').value.trim(),
    c=parseInt($('slc').value,10),
    dg=+n.replace(/\D/g,'');

  if(!canManageRooms())return ko('Action réservée aux directeurs / administrateurs du centre.');
  if(!n)return ko('Saisissez le nom de la salle.');
  if(!ty)return ko('Saisissez le type de salle.');
  if(!(c>0&&c<=500))return ko('Saisissez une capacité valide (1 à 500).');

  const doublon=ROOMS.some(r=>{
    if(EDIT_ROOM_ID!==null && r===EDIT_ROOM_ID)return false;
    return norm(sn(r))===norm(n) || (dg&&SID[dg]&&dg!==EDIT_ROOM_ID);
  });
  if(doublon)return ko('Cette salle existe déjà.');

  if(b)b.disabled=true;

  let r;
  if(EDIT_ROOM_ID!==null){
    let q=sb.from('salles').update({nom:n,type:ty,capacite:c}).eq('id',SID[EDIT_ROOM_ID]);
    if(me.centreId)q=q.eq('centre_id',me.centreId);
    r=await q;
  }else{
    // Une salle appartient toujours au centre courant.
    // `ctr()` ne renseigne centre_id que pour le SUPER_ADMIN ;
    // le Directeur doit donc transmettre explicitement son centre_id.
    const centre_id=me&&me.sup?CURRENT_CENTRE_ID:(me&&me.centreId)||null;
    r=await sb.from('salles').insert({nom:n,type:ty,capacite:c,centre_id});
  }

  if(b)b.disabled=false;
  if(r.error)return ko('Erreur : '+r.error.message);

  const wasEdit=EDIT_ROOM_ID!==null;
  EDIT_ROOM_ID=null;
  await load();
  initForm();
  const fv=$('fr').value;
  opts($('fr'),[['','Toutes les salles'],...ROOMS.map(x=>[x,sn(x)+' · '+RI[x][0]])]);
  $('fr').value=fv;
  render();
  m.className='msg ok';
  m.textContent=wasEdit?`Salle modifiée : ${n}.`:`Salle ajoutée : ${n}.`;
  setTimeout(()=>$('dsl').close(),600);
};

/* ---------- Gérer les centres (SUPER_ADMIN) ---------- */
/* Liste des droits possibles pour un centre.
 * La clé est utilisée dans la table centres.droits (JSON).
 * Le libellé est affiché dans l'interface.
 */
const DROITS = [
  ['etudiants', 'Étudiants'],
  ['formateurs', 'Formateurs'],
  ['cours', 'Cours'],
  ['planning', 'Planning'],
  ['salles', 'Salles'],
  ['presences', 'Présences'],
  ['certificats', 'Certificats'],
  ['supports', 'Supports'],
  ['documents', 'Documents'],
  ['statistiques', 'Statistiques'],
  ['rapports', 'Rapports'],
  ['import_excel', 'Import Excel'],
  ['export_excel', 'Export Excel']
];
 let CEN=[],CENSUB=false,ZID=null;
const zfd=d=>d?d.split('-').reverse().join('/'):'',zvide='Non défini',
  zdr=c=>DROITS.filter(([k])=>!c.droits||c.droits[k]!==false).length;
async function loadCentres(){
  if(!me||!me.sup)return;
  const r=await sb.from('centres').select('*').order('created_at');
  if(r.error){$('zt').innerHTML='';$('znote').textContent='Erreur : '+r.error.message;return}
  CEN=r.data||[];
  CENSUB=!(await sb.from('centres').select('type_abonnement,statut_abonnement,date_debut,date_expiration,droits').limit(1)).error;
  const P=await zprof();
  CEN.forEach(c=>{if(!P){c._n=null;c._u=null;return}const u={director:0,admin:0,super_admin:0,formateur:0,etudiant:0};P.filter(x=>x.centre_id===c.id).forEach(x=>{if(x.role in u)u[x.role]++});c._u=u;c._n=P.filter(x=>x.centre_id===c.id).length});
  renderCentres();loadBandeau()}
async function zprof(){let a=[],i=0;for(;;){const r=await sb.from('profiles').select('centre_id,role').range(i,i+999);if(r.error)return null;a=a.concat(r.data||[]);if((r.data||[]).length<1000)return a;i+=1000}}
const zud=c=>c._u?'Directeurs : '+c._u.director+' · Formateurs : '+c._u.formateur+' · Étudiants : '+c._u.etudiant+(c._u.admin?' · Administrateurs : '+c._u.admin:'')+(c._u.super_admin?' · Super administrateurs : '+c._u.super_admin:''):'';

