/* ---------- Gérer les formations (SUPER_ADMIN) ---------- */
async function loadFormations(){

  const container = $('fgFormationsTable');

  if(!container) return;

  if(!CURRENT_CENTRE_ID){
    container.innerHTML = `


        Centre introuvable.

    `;
    return;
  }

  container.innerHTML = `


      Chargement des formations...

  `;

  const r = await sb
    .from('formations')
    .select('id,nom,duree,description,actif')
    .eq('centre_id',CURRENT_CENTRE_ID)
    .order('nom');

  if(r.error){

    console.error('ERREUR CHARGEMENT FORMATIONS:',r.error);

    container.innerHTML = `


        Erreur lors du chargement des formations.

    `;

    return;
  }

  if(!r.data || !r.data.length){

    container.innerHTML = `


        Aucune formation.

    `;

    return;
  }

  container.innerHTML = `



      ${r.data.map(f => `
















                ${esc(f.nom || '')}



                ${f.actif ? 'Active' : 'Inactive'}







Durée :
              ${esc(f.duree || 'Non définie')}




              ${esc(f.description || 'Aucune description.')}






                Modifier



                Supprimer








      `).join('')}




  `;

}






