document.addEventListener('click', async e => {

  const btn = e.target.closest('[data-edit-formation]');

  if(!btn) return;

  const id = +btn.dataset.editFormation;

  if(!id) return;

  const r = await sb
    .from('formations')
    .select('id,nom,duree,description,actif')
    .eq('id',id)
    .eq('centre_id',CURRENT_CENTRE_ID)
    .maybeSingle();

  if(r.error || !r.data){
    console.error('ERREUR FORMATION:',r.error);
    return;
  }


  const f = r.data;

  FG_EDIT_FORMATION_ID = f.id;

  $('fgFormationForm').classList.remove('hidden');

    // Charger les modules disponibles pour ce centre

  await fgLoadModuleCatalogue();
  await fgLoadModuleDomains();
  await fgLoadFormationModules(f.id);
  fgRenderSelectedModuleBadges();


  $('fgFormationNom').value = f.nom || '';
  $('fgFormationDuree').value = f.duree || '';
  $('fgFormationDescription').value = f.description || '';

  $('fgFormationNote').textContent =
    'Modification de la formation : ' + f.nom;

  $('fgFormationNom').focus();

});




/* ---------- Chargement des groupes (SUPER_ADMIN) ---------- */

async function loadGroupes(){

  const container = $('fgGroupesTable');

  if(!container) return;

  if(!CURRENT_CENTRE_ID){
    container.innerHTML = `


        Centre introuvable.

    `;
    return;
  }



  container.innerHTML = `


      Chargement des groupes...

  `;


   const effectifsResultat = await sb
    .from('etudiants')
    .select('groupe_id')
    .eq('centre_id', CURRENT_CENTRE_ID);

  if (effectifsResultat.error) {
    console.error(
      'ERREUR EFFECTIFS GROUPES:',
      effectifsResultat.error
    );
    container.innerHTML =
      '
Impossible de charger les effectifs.';
    return;
  }

  const effectifsParGroupe = {};

  (effectifsResultat.data || []).forEach(etudiant => {
    if (etudiant.groupe_id != null) {
      effectifsParGroupe[etudiant.groupe_id] =
        (effectifsParGroupe[etudiant.groupe_id] || 0) + 1;
    }
  });

  const r = await sb
    .from('groupes')
    .select(`
      id,
      nom,
      formation_id,
      date_debut,
      date_fin,
      capacite,
      actif,
      formations (
        nom
      )
    `)
    .eq('centre_id',CURRENT_CENTRE_ID)
    .order('nom');

  if(r.error){

    console.error('ERREUR CHARGEMENT GROUPES:',r.error);

    container.innerHTML = `


        Erreur lors du chargement des groupes.

    `;

    return;
  }

  if(!r.data || !r.data.length){

    container.innerHTML = `


        Aucun groupe.

    `;

    return;
  }

  container.innerHTML = `



      ${r.data.map(g => `














                ${esc(g.nom || '')}




                Effectif :
                ${effectifsParGroupe[g.id] || 0}
                / ${Number(g.capacite || 30)} étudiants




                Places restantes :
                ${Math.max(0, Number(g.capacite || 30) - (effectifsParGroupe[g.id] || 0))}








              Formation :

                ${esc(g.formations?.nom || 'Formation inconnue')}



                Capacité maximale : ${Number(g.capacite || 30)} étudiants










                  Date de début



                  ${esc(g.date_debut || 'Non définie')}







                  Date de fin



                  ${esc(g.date_fin || 'Non définie')}










                Supprimer








      `).join('')}




  `;

}

