let FG_FORMATION_SELECTIONNEE = null;

async function afficherGroupesFormation(formationId, formationNom){

  FG_FORMATION_SELECTIONNEE = formationId;

  $('fgGroupesFormationTitre').textContent =
    'Groupes de la formation : ' + formationNom;

  $('fgGroupesFormationNote').textContent =
    'Chargement des groupes...';

  $('fgGroupesFormationListe').innerHTML = '';

  const r = await sb
    .from('groupes')
    .select('id,nom,date_debut,date_fin,actif,capacite')
    .eq('centre_id', CURRENT_CENTRE_ID)
    .eq('formation_id', formationId)
    .order('nom');


console.log('SESSION UTILISATEUR :', await sb.auth.getUser());


  if(r.error){
    console.error('ERREUR GROUPES FORMATION:', r.error);

    $('fgGroupesFormationNote').textContent =
      'Erreur lors du chargement des groupes.';

    return;
  }

  if(!r.data || !r.data.length){
    $('fgGroupesFormationNote').textContent =
      'Aucun groupe pour cette formation.';

    return;
  }


  // Calcul du nombre d'étudiants distincts par groupe
const groupesIds = r.data.map(g => g.id);

const coursRes = await sb
  .from('cours')
  .select('*')
  .in('groupe_id', groupesIds);

  console.log('COURS DE LA FORMATION :', coursRes.data);

if (coursRes.error) {
  console.error('Erreur chargement cours :', coursRes.error);
  $('fgGroupesFormationNote').textContent =
    'Erreur lors du chargement des cours.';
  return;
}

const cours = coursRes.data || [];
const coursIds = cours.map(c => c.id);

const inscriptionsRes = coursIds.length
  ? await sb
      .from('inscriptions')
      .select('cours_id, etudiant_id')
      .in('cours_id', coursIds)
  : { data: [], error: null };

if (inscriptionsRes.error) {
