    'Erreur chargement inscriptions :',
    inscriptionsRes.error
  );
  $('fgGroupesFormationNote').textContent =
    'Erreur lors du chargement des inscriptions.';
  return;
}

// Création d'un objet pour stocker les étudiants distincts par groupe
const etudiantsParGroupe = {};

groupesIds.forEach(id => {
  etudiantsParGroupe[id] = new Set();
});

const groupeParCours = {};

cours.forEach(c => {
  groupeParCours[c.id] = c.groupe_id;
});

(inscriptionsRes.data || []).forEach(inscription => {
  const groupeId = groupeParCours[inscription.cours_id];

