    groupeId != null &&
    inscription.etudiant_id != null &&
    etudiantsParGroupe[groupeId]
  ) {
    etudiantsParGroupe[groupeId].add(
      inscription.etudiant_id
    );
  }
});

const nombreEtudiantsParGroupe = {};

groupesIds.forEach(id => {
  nombreEtudiantsParGroupe[id] =
    etudiantsParGroupe[id].size;
});


  $('fgGroupesFormationNote').textContent =
    r.data.length + ' groupe(s) associé(s) à cette formation.';

    const effectifsResultat = await sb
  .from('etudiants')
  .select('groupe_id')
