async function loadBandeau(){const el=$('cbar');

  if(me && me.sup){
    return;
  }
el.classList.add('hidden');
  try{if(!me||me.role!=='Admin')return;
  // On récupère l'id du centre rattaché au profil de l'utilisateur.
    const pr=await sb.from('profiles').select('centre_id').eq('id',me.uid).maybeSingle(),cid=pr.data&&pr.data.centre_id;if(!cid)return;
  // On récupère les infos du centre depuis la table `centres`.
    const c=(await sb.from('centres').select('*').eq('id',cid).maybeSingle()).data;if(!c)return;
  // On calcule le nombre de jours restants avant expiration.
    const j=c.date_expiration?Math.round((new Date(c.date_expiration+'T12:00')-new Date(iso(new Date())+'T12:00'))/864e5):null,
      jt=j===null?'':j<0?`Expiré depuis ${-j} j`:j===0?`Expire aujourd'hui`:`${j} jour${j>1?'s':''} restant${j>1?'s':''}`;
  // On affiche le bandeau avec les infos du centre.  
      const any=c.type_abonnement||c.statut_abonnement||c.date_expiration;
    el.innerHTML=
  (c.logo_url
    ? ``
    : ''
  )
  + `${esc(c.nom)}`+(any?(c.type_abonnement?`Abonnement : ${esc(c.type_abonnement)}`:'')+(c.statut_abonnement?`Statut : ${esc(c.statut_abonnement)}`:'')+(c.date_expiration?`Expiration : ${zfd(c.date_expiration)}`+jt:''):'Abonnement : non défini');
    el.classList.remove('hidden')}catch(e){}}


