  }
  if(ins.error)return ko(ins.error.code==='23P01'?'Conflit : ce créneau est déjà occupé (salle ou formateur).':'Erreur : '+ins.error.message);
  const cid=EID||(ins.data&&ins.data.id);


// ---------- Gestion des inscriptions ----------
if (cid) {
  const want = [
    ...document.querySelectorAll('#cst input:checked')
  ].map(x => +x.value);

  const have = ENR
    .filter(n => n.cours_id === cid)
    .map(n => n.etudiant_id);

  const add = want.filter(x => !have.includes(x));
  const del = have.filter(x => !want.includes(x));

  // Vérifier la capacité du groupe avant les nouvelles inscriptions
  const groupeId = $('fcgroupe').value;

  if (groupeId && add.length) {
    const groupeResult = await sb
      .from('groupes')
      .select('capacite')
      .eq('id', groupeId)
      .single();

    if (groupeResult.error) {
      alert('Impossible de vérifier la capacité du groupe.');
      return;
    }

    const capacite = Number(groupeResult.data.capacite || 30);

    const coursResult = await sb
      .from('cours')
      .select('id')
      .eq('groupe_id', groupeId);

    if (coursResult.error) {
      alert('Impossible de vérifier les cours du groupe.');
      return;
    }

    const coursIds = (coursResult.data || []).map(c => c.id);

    const inscriptionsResult = coursIds.length
      ? await sb
          .from('inscriptions')
          .select('etudiant_id')
          .in('cours_id', coursIds)
      : { data: [], error: null };

    if (inscriptionsResult.error) {
      alert('Impossible de vérifier les étudiants du groupe.');
      return;
    }

    const etudiantsGroupe = new Set(
      (inscriptionsResult.data || []).map(i => i.etudiant_id)
    );

    // Ne pas compter deux fois les étudiants déjà inscrits au groupe
    add.forEach(id => etudiantsGroupe.add(id));

    // Recalculer les étudiants après les suppressions demandées
    del.forEach(id => {
      const encoreInscrit = (inscriptionsResult.data || [])
        .some(i => i.etudiant_id === id &&
          coursIds.some(coursId =>
            coursId !== cid &&
            ENR.some(e =>
              e.cours_id === coursId &&
              e.etudiant_id === id
            )
          )
        );

      if (!encoreInscrit) etudiantsGroupe.delete(id);
    });

    if (etudiantsGroupe.size > capacite) {
      alert(
        `Groupe complet ! Capacité : ${capacite} étudiants. ` +
        `Effectif après inscription : ${etudiantsGroupe.size}.`
      );
      return;
    }
  }

  if (add.length) {
    const resultatAjout = await sb
      .from('inscriptions')
      .insert(add.map(x => ({
        etudiant_id: x,
        cours_id: cid
      })));

    if (resultatAjout.error) {
      alert('Erreur lors de l’inscription des étudiants.');
      console.error(resultatAjout.error);
      return;
    }
  }

  if (del.length) {
    const resultatSuppression = await sb
      .from('inscriptions')
      .delete()
      .eq('cours_id', cid)
      .in('etudiant_id', del);

    if (resultatSuppression.error) {
      alert('Erreur lors de la suppression des inscriptions.');
      console.error(resultatSuppression.error);
      return;
    }
  }

  await refreshEtu();
}


