/* ---------- Chargement des données (Admin) ---------- */
async function load(){

  const cq=(table,columns)=>{
    let q=sb.from(table).select(columns);

    if(CURRENT_CENTRE_ID){
      q=q.eq('centre_id',CURRENT_CENTRE_ID);
    }

    return q;
  };

  // Récupération des données depuis Supabase
  const q=await Promise.all([

    sb.from('matieres')
      .select('id,code,nom,icone,domaine_id'),

    cq('salles','id,nom,type,capacite')
      .order('nom'),

    cq('formateurs','id,nom,profile_id,email')
      .order('id'),

    sb.from('formateur_matieres')
      .select('formateur_id,matiere_id'),

    cq('cours','*'),

    sb.from('domaines')
      .select('id,nom'),

    cq('annulations','cours_id,date'),

    cq('fermetures','*')

  ]);

  q.slice(0,6).forEach(x=>{
    if(x.error) throw x.error;
  });

  const [m,s,f,fm,c,dm,an,fe]=q.map(x=>x.data||[]);

  MID={};
  CODE={};

  m.forEach(x=>{
    MID[x.code]=x.id;
    CODE[x.id]=x.code;
  });

  DID={};

  const DN={};

  dm.forEach(x=>{
    DID[x.nom]=x.id;
    DN[x.id]=x.nom;
  });

  Object.keys(S).forEach(k=>delete S[k]);

  m.forEach(x=>{
    S[x.code]=[
      x.nom,
      POLEK[DN[x.domaine_id]]||'lang',
      x.icone,
      null
    ];
  });

  SID={};
  RN={};
  RNM={};
  ROOMS.length=0;

  s.forEach(x=>{
    let n=+x.nom.replace(/\D/g,'');

    const ch=!n||SID[n];

    if(ch){
      n=1000;
      while(SID[n]) n++;
      RNM[n]=x.nom;
    }

    SID[n]=x.id;
    RN[x.id]=n;
    ROOMS.push(n);
    RI[n]=[x.type,x.capacite];
  });

  ROOMS.sort((a,b)=>a-b);

  T.splice(
    0,
    T.length,
    ...f.map(x=>({
      id:x.id,
      pid:x.profile_id,
      mail:x.email,
      n:x.nom,
      s:fm
        .filter(y=>y.formateur_id===x.id)
        .map(y=>CODE[y.matiere_id])
    }))
  );

  RAW=c;

  ANN=new Set(
    an.map(x=>x.cours_id+'|'+x.date)
  );

  FERM={};

  fe.forEach(x=>{
    FERM[x.date]=x.libelle||'Fermé';
  });

  buildWeek();
}

/* ---------- Filtres du planning ---------- */

let PL_FORMATIONS = [];
let PL_GROUPES = [];
let PL_FORMATION_MODULES = [];

async function chargerFiltresPlanning() {
  const formationSelect = $('fp');
  const groupeSelect = $('fgPlanning');
  const moduleSelect = $('fmPlanning');
  const formateurSelect = $('ft');

  if (!formationSelect || !groupeSelect ||
      !moduleSelect || !formateurSelect) return;

  const centreId = CURRENT_CENTRE_ID;

  let qFormations = sb
    .from('formations')
    .select('id,nom,duree')
    .order('nom');

  let qGroupes = sb
    .from('groupes')
    .select('id,nom,formation_id,date_debut,date_fin,actif')
    .order('nom');

  if (centreId) {
    qFormations = qFormations.eq('centre_id', centreId);
    qGroupes = qGroupes.eq('centre_id', centreId);
  }

  const [formationsResult, groupesResult, modulesResult] =
    await Promise.all([
      qFormations,
      qGroupes,
      sb.from('formation_matieres')
        .select('formation_id,matiere_id')
    ]);

  if (formationsResult.error) throw formationsResult.error;
  if (groupesResult.error) throw groupesResult.error;
  if (modulesResult.error) throw modulesResult.error;

  PL_FORMATIONS = formationsResult.data || [];
  PL_GROUPES = groupesResult.data || [];
  PL_FORMATION_MODULES = modulesResult.data || [];

  formationSelect.innerHTML =
    'Toutes les formations' +
    PL_FORMATIONS.map(f =>
      `${esc(f.nom)}`
    ).join('');

  groupeSelect.innerHTML =
    'Tous les groupes';

  moduleSelect.innerHTML =
    'Tous les modules';

  groupeSelect.disabled = true;
  moduleSelect.disabled = true;

  const formateurs = T
    .map((t, i) => ({ id: i, nom: t.n }))
    .sort((a, b) => a.nom.localeCompare(b.nom, 'fr'));

  formateurSelect.innerHTML =
    'Tous les formateurs' +
    formateurs.map(t =>
      `${esc(t.nom)}`
    ).join('');

  if (me && me.role === 'Formateur' && me.tid !== undefined) {
    formateurSelect.value = String(me.tid);
    formateurSelect.disabled = true;
  } else {
    formateurSelect.disabled = false;
  }

  formationSelect.onchange = () => {
    const formationId = formationSelect.value;

    const groupes = PL_GROUPES.filter(g =>
      !formationId ||
      String(g.formation_id) === String(formationId)
    );

    groupeSelect.innerHTML =
      'Tous les groupes' +
      groupes.map(g =>
        `${esc(g.nom)}`
      ).join('');

    groupeSelect.disabled = !formationId;

    const moduleIds = PL_FORMATION_MODULES
      .filter(m =>
        !formationId ||
        String(m.formation_id) === String(formationId)
      )
      .map(m => String(m.matiere_id));

    const modules = Object.entries(MID)
      .filter(([code, id]) =>
        moduleIds.includes(String(id))
      )
      .map(([code, id]) => ({
        id: code,
        nom: S[code]?.[0] || code
      }))
      .sort((a, b) => a.nom.localeCompare(b.nom, 'fr'));

    moduleSelect.innerHTML =
      'Tous les modules' +
      modules.map(m =>
        `${esc(m.nom)}`
      ).join('');

    moduleSelect.disabled = !formationId;

    render();
  };

  groupeSelect.onchange = render;
  moduleSelect.onchange = render;
  formateurSelect.onchange = render;

  render();
}

/* ---------- Sélecteur de centre actif (SUPER_ADMIN) ---------- */
async function renderSuperCentreSelector(){

  const el = $('cbar');

  if(!el) return;

  if(!me || !me.sup){
    el.classList.add('hidden');
    return;
  }

  if(!SUPER_CENTRES || !SUPER_CENTRES.length){
    el.innerHTML = 'Centre actif : Aucun centre disponible';
    el.classList.remove('hidden');
    return;
  }

  /* ---------- Sélecteur de centre actif ---------- */

  el.innerHTML = `









        Centre actif :


          ${SUPER_CENTRES.map(c => `

              ${esc(c.nom)}

          `).join('')}




  `;

  el.classList.remove('hidden');

  /* ---------- Logo du centre actif ---------- */

  const logoEl = $('superCentreLogo');

  if(logoEl){

    const centreActif = SUPER_CENTRES.find(
      c => c.id === CURRENT_CENTRE_ID
    );

    if(centreActif){

      const r = await sb
        .from('centres')
        .select('logo_url')
        .eq('id', centreActif.id)
        .maybeSingle();

      if(r.data && r.data.logo_url){

        logoEl.innerHTML =
          ``;

      }else{

        logoEl.innerHTML =
          '🏫';

      }
    }
  }

  const select = $('superCentreSelect');

  if(!select) return;

  select.onchange = async function(){

    const centre = SUPER_CENTRES.find(
      c => c.id === this.value
    );

    if(!centre) return;

    CURRENT_CENTRE_ID = centre.id;
    CURRENT_CENTRE_NAME = centre.nom;

    localStorage.setItem(
      'schoolplans_current_centre',
      centre.id
    );

    await load();

    const activeTab = document.querySelector('.tabs button.on');

    if(activeTab){

      const v = activeTab.dataset.v;

      if(v === 'vs') await loadEtu();
      if(v === 'vp') await loadPres();
      if(v === 'vc') await loadCert();
      if(v === 'vk') await loadDocs();
      if(v === 'vd') await loadDash();
      if(v === 'vi') await loadDem();
    }

    refreshBadge();

    render();
  };
}

