const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&','<':'<','>':'>','"':'"',"'":'''}[c]));
const amr=s=>{try{return JSON.parse(atob(s.access_token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/'))).amr||[]}catch(e){return[]}};
const isPwd=s=>amr(s).some(a=>a.method==='password');
let EID=0,AD=Math.min((new Date().getDay()+6)%7,5);
const dOf=d=>{const n=new Date(),cur=(n.getDay()+6)%7,dd=d===undefined?(cur>5?0:cur):d;n.setDate(n.getDate()+((dd-cur+7)%7));return n.toLocaleDateString('sv-SE')};



/* ---------- Chargement des groupes de cours ---------- */
async function chargerGroupesCours() {
  const select = $('fcgroupe');

  select.innerHTML = `
    Sélectionner un groupe
  `;

  if (!CURRENT_CENTRE_ID) {
    return;
  }

  const r = await sb
    .from('groupes')
    .select('id, nom, capacite')
    .eq('centre_id', CURRENT_CENTRE_ID)
    .eq('actif', true)
    .order('nom');

  if (r.error) {
    console.error(
      'Erreur chargement des groupes :',
      r.error
    );

    select.innerHTML = `
      Erreur de chargement
    `;
    return;
  }

  select.innerHTML = `
    Sélectionner un groupe
    ${(r.data || []).map(g => `

        ${esc(g.nom)} — ${Number(g.capacite || 30)} places

    `).join('')}
  `;
}



/* ---------- Formulaire de cours ---------- */
async function openCours(o){
  o=o||{};

  if(me.role==='Formateur' && me.tid===undefined){
    alert("Votre compte n'est pas encore relié à une fiche formateur. Contactez l'administration.");
    return;
  }

  if(me.role==='Formateur' && o.id && o.t!==me.tid)
    return;

  EID=o.id||0;

  $('dct').textContent=EID?'Modifier le cours':'Ajouter un cours';

// Charger les groupes de cours pour le centre actif
  await chargerGroupesCours();

const coursActuel = RAW.find(c => c.id === EID);

$('fcgroupe').value =
  coursActuel?.groupe_id
    ? String(coursActuel.groupe_id)
    : '';

  // Formateur
  $('ftr').disabled=me.role==='Formateur';

  if(me.role==='Formateur'){
    $('ftr').value=me.tid;
  }else{
    $('ftr').value=(o.t!==undefined && o.t>=0)?o.t:'';
  }

  // Matière
  $('fs').value=o.k||'';

  // Recalcul bidirectionnel
  fsOpts();

  $('fd').value=o.date||dOf(o.d);
  $('fty').value=o.once?'o':'w';
  EONCE=!!o.once;
  ECDATE=o.date||'';

  $('fcan').classList.toggle('hidden',!(EID&&!o.once));

  $('fh').value=o.s||9;
  $('fe').value=o.e||(o.s?Math.min(o.s+2,19):11);
  $('fsr').value=o.r||'';

  $('cst').innerHTML=ETU.length
    ?ETU.map(x=>
      `
        n.cours_id===EID&&n.etudiant_id===x.id)
          ?' checked':''
        }>
        ${esc(stuName(x))}
      `
    ).join('')
    :'Aucun étudiant chargé. Rechargez la page après validation de la connexion Supabase.';

  $('fdel').classList.toggle('hidden',!EID);
  $('am').textContent='';

  $('dc').showModal();
}


$('fdel').onclick=async()=>{
  if(!EID)return;
  if(me.role==='Formateur'){
    const own=RAW.some(r=>r.id===EID&&me.tid!==undefined&&r.formateur_id===T[me.tid]?.id);
    if(!own){alert('Vous ne pouvez supprimer que vos propres cours.');return;}
  }
  if(!confirm('Supprimer ce cours ?'))return;
  let q=sb.from('cours').delete().eq('id',EID);
  const centreId=me&&me.sup?CURRENT_CENTRE_ID:(me&&me.centreId)||null;
  if(centreId)q=q.eq('centre_id',centreId);
  const r=await q;
  if(r.error){alert('Suppression impossible : '+r.error.message);return}
  await load();render();$('dc').close();
};
