/* ---------- Calendrier daté, jours fermés, étudiants, présences ---------- */
let RAW=[],ANN=new Set(),FERM={},XC=[],ETU=[],ENR=[],PR=[],EONCE=false,ECDATE='';
const iso=d=>d.toLocaleDateString('sv-SE');
const monday=d=>{const x=new Date(d);x.setHours(12,0,0,0);x.setDate(x.getDate()-((x.getDay()+6)%7));return x};
const addD=(d,n)=>{const x=new Date(d);x.setDate(x.getDate()+n);return x};
let WK=monday(new Date());
const wdate=i=>iso(addD(WK,i));


function buildWeek(){C=[];XC=[];
  RAW.forEach(r=>{const i=r.jour,ds=wdate(i);if(i>5||FERM[ds]||dsr.valable_au)return;
    const o={id:r.id,d:i,s:hh(r.debut),e:hh(r.fin),k:CODE[r.matiere_id],
      t:T.findIndex(t=>t.id===r.formateur_id),r:RN[r.salle_id],date:ds,
      once:!!r.valable_du&&r.valable_du===r.valable_au};
    if(ANN.has(r.id+'|'+ds)){o.x=1;XC.push(o)}else C.push(o)});
  if(me&&me.role==='Formateur'&&me.tid===undefined){C=[];XC=[]}}


  function wkLabel(){const b=addD(WK,5),f=d=>d.toLocaleDateString('fr-FR',{day:'numeric',month:'long'});$('wl').textContent='Semaine du '+f(WK)+' au '+f(b)+' '+b.getFullYear()}
$('wp').onclick=()=>{WK=addD(WK,-7);buildWeek();render()};
// $('wnx').onclick=()=>{WK=addD(WK,7);buildWeek();render()};

function finPeriodePlanning() {
  const formationId = $('fp')?.value || '';
  const groupeId = $('fgPlanning')?.value || '';

  if (groupeId) {
    return PL_GROUPES.find(
      g => String(g.id) === String(groupeId)
    )?.date_fin || null;
  }

  if (formationId) {
    const fins = PL_GROUPES
      .filter(g =>
        String(g.formation_id) === String(formationId) &&
        g.date_fin
      )
      .map(g => g.date_fin)
      .sort();

    return fins.length ? fins[fins.length - 1] : null;
  }

  return null;
}

$('wnx').onclick = () => {
  const prochaineSemaine = addD(WK, 7);
  const fin = finPeriodePlanning();

  if (fin) {
    const dateFin = new Date(fin + 'T12:00:00');
    const derniereSemaine = monday(dateFin);

    if (prochaineSemaine > derniereSemaine) {
      return;
    }
  }

  WK = prochaineSemaine;
  buildWeek();
  render();
};

$('wt').onclick=()=>{WK=monday(new Date());buildWeek();render()};
