/* ---------- Chargement des groupes d'étudiants ---------- */

async function chargerGroupesEtudiants(groupeSelectionne = null) {
  const select = $('egroupe');
  const info = $('egroupeInfo');

  select.innerHTML = 'Aucun groupe';
  info.textContent = 'Chargement des groupes...';

  if (!CURRENT_CENTRE_ID) {
    info.textContent = 'Centre introuvable.';
    return;
  }

  const [rg, re] = await Promise.all([
    sb.from('groupes')
      .select('id, nom, actif, capacite, centre_id')
      .eq('centre_id', CURRENT_CENTRE_ID)
      .order('nom'),

    sb.from('etudiants')
      .select('id, groupe_id')
      .eq('centre_id', CURRENT_CENTRE_ID)
  ]);

  if (rg.error || re.error) {
    info.textContent = 'Impossible de charger les groupes.';
    console.error('Chargement des groupes :', rg.error || re.error);
    return;
  }

  const groupes = rg.data || [];
  const etudiants = re.data || [];

  const effectifs = {};
  etudiants.forEach(e => {
    if (e.groupe_id != null) {
      effectifs[e.groupe_id] = (effectifs[e.groupe_id] || 0) + 1;
    }
  });

  groupes.forEach(g => {
    const effectif = effectifs[g.id] || 0;
    const capacite = Number(g.capacite || 0);
    const estActuel = String(g.id) === String(groupeSelectionne);
    const complet = effectif >= capacite;

    // Seul le groupe actuellement affecté peut rester sélectionné
    // s'il est devenu inactif ou complet.
    if (!g.actif && !estActuel) return;
    if (complet && !estActuel) return;

    const option = document.createElement('option');
    option.value = g.id;
    option.textContent =
      `${g.nom} — ${effectif}/${capacite} places` +
      (!g.actif ? ' (inactif — affectation actuelle)' : '') +
      (complet ? ' (complet — affectation actuelle)' : '');

    select.appendChild(option);
  });

  select.value = groupeSelectionne == null ? '' : String(groupeSelectionne);

  info.textContent = groupes.length
    ? 'Seuls les groupes actifs et disposant de places sont proposés.'
    : 'Aucun groupe créé dans ce centre.';
}


