    function openStu(x){

      ESID=x?x.id:0;
      $('stt').textContent=x?'Modifier l\'étudiant':'Ajouter un étudiant';
      $('ep').value=x&&x.prenom||'';
      $('en').value=x&&x.nom||'';
      $('et2').value=x&&x.telephone||'';
      $('ee').value=x&&x.email||'';
      $('ev').value=x&&x.ville||'';
      $('ea').value=x&&x.adresse||'';
      opts($('eniv'),[['','-'],...NIV.map(v=>[v,v])]);
      $('eniv').value=x&&x.niveau_etudes||'';
      $('ec').innerHTML=RAW.length?RAW
      .slice()
      .sort((a,b)=>a.jour-b.jour||(a.debut`n.etudiant_id===ESID&&n.cours_id===r.id)?' checked':''}>${esc(crsLabel(r))}`)
        .join(''):'Aucun cours n\'est encore créé.';
      $('edel').classList.toggle('hidden',!ESID);$('eacc').classList
      .toggle('hidden',!(x&&x.email));
      $('em').textContent='';

      chargerGroupesEtudiants(x ? x.groupe_id : null);

      $('dstu').showModal()
    }


